// Des: Notify the owner: OS toast, hub alert line, alerts file; one plain line, never chat text
// Flo: sanitize line > for each channel in config order: toast, hubz (stderr), file (append) > count delivered
// I/O: Conf channel list + stat dir + line (caller) > Done flags; alerts.txt appended
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const conf = @import("cf-conf-load.zig"); const file = @import("st-stor-file.zig");
const CF = .{ .maxl = 200, .maxo = 4096, .alrt = "alerts.txt", .keep = 64 * 1024 };
pub const Done = struct { toast: bool = false, hubz: bool = false, file: bool = false };
pub fn plain(aren: std.mem.Allocator, what: []const u8, todo: []const u8) ![]u8 { return std.fmt.allocPrint(aren, "za: {s}. {s}", .{ what, todo }); }
pub fn clean(aren: std.mem.Allocator, text: []const u8) ![]u8 { var out: std.ArrayList(u8) = .empty; for (text) |chr| { if (out.items.len >= CF.maxl) break; if (chr == '"' or chr == '\'' or chr == '`' or chr == '$' or chr == '\\' or chr == '%' or chr == '&' or chr == '|' or chr == '<' or chr == '>') { try out.append(aren, ' '); } else if (chr < 0x20) { try out.append(aren, ' '); } else try out.append(aren, chr); } return out.items; }
fn toast(aren: std.mem.Allocator, iozz: std.Io, line: []const u8) bool { const argv: []const []const u8 = switch (builtin.os.tag) { .windows => &.{ "powershell", "-NoProfile", "-NonInteractive", "-Command", std.fmt.allocPrint(aren, "Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; $n=New-Object System.Windows.Forms.NotifyIcon; $n.Icon=[System.Drawing.SystemIcons]::Information; $n.Visible=$true; $n.ShowBalloonTip(10000,'za','{s}','Info'); Start-Sleep -Seconds 2; $n.Dispose()", .{line}) catch return false }, .macos => &.{ "osascript", "-e", std.fmt.allocPrint(aren, "display notification \"{s}\" with title \"za\"", .{line}) catch return false }, else => &.{ "notify-send", "za", line } }; const res = std.process.run(aren, iozz, .{ .argv = argv, .stdout_limit = .limited(CF.maxo), .stderr_limit = .limited(CF.maxo) }) catch return false; return switch (res.term) { .exited => |code| code == 0, else => false }; }
fn appendFile(aren: std.mem.Allocator, iozz: std.Io, stat: []const u8, line: []const u8, now_ms: i64) bool { const path = std.fs.path.join(aren, &.{ stat, CF.alrt }) catch return false; const old = file.fileRead(aren, iozz, path, CF.keep) catch ""; const keep = if (old.len > CF.keep / 2) old[old.len - CF.keep / 2 ..] else old; const body = std.fmt.allocPrint(aren, "{s}{d} {s}\n", .{ keep, now_ms, line }) catch return false; file.fileAtom(aren, iozz, path, body) catch return false; return true; }
pub fn send(aren: std.mem.Allocator, iozz: std.Io, cfg: conf.Conf, stat: []const u8, text: []const u8, now_ms: i64, real_toast: bool) !Done { const line = try clean(aren, text); var done: Done = .{}; for (cfg.noti_chai_orde) |chn| { if (std.mem.eql(u8, chn, "toast")) { if (real_toast) done.toast = toast(aren, iozz, line); } else if (std.mem.eql(u8, chn, "hubz")) { std.debug.print("ALERT: {s}\n", .{line}); done.hubz = true; } else if (std.mem.eql(u8, chn, "file")) { done.file = appendFile(aren, iozz, stat, line, now_ms); } } return done; }
